/** * 通过单独clip的位置返回包括date的位置 * */fun countDateBeforeClip(clipPosition: Int): Int {    var count = 0    var clipCount = 0    for (item in itemList) {        if (item is String) count += 1        else clipCount += 1        if (clipCount == clipPosition + 1) break    }    return count + clipPosition}



