/*** * 滚动到最后播放的clip */private fun scrollViewToLastClip(recyclerView: RecyclerView, layoutManager: GridLayoutManager) {    // 包括date的下标    val positionWithDate =        viewModel.searchResultAdapter.countDateBeforeClip(currentClipPosition)    if (positionWithDate &gt; 0) {        if (recyclerView.layoutManager == null || recyclerView.adapter == null) {            logger.d(TAG, "RecyclerView layout or adapter is not set")            return        }        // 滚动位置是否在可见范围内        val lastVisiblePosition = layoutManager.findLastVisibleItemPosition()        val rowHeight = if (positionWithDate &lt; lastVisiblePosition) {            layoutManager.findViewByPosition(positionWithDate)?.bottom        } else {            resources.displayMetrics.heightPixels        }        /**         * 滚动到最后播放的clip可见位置,再整体移到顶部         * 24 safe_area_top_guide         * 48 导航栏         * 16 recyclerView margin-top         * 96 视频高度         * 4 clip padding-top         * */        recyclerView.scrollToPosition(positionWithDate)        val scrollDistance = MeasureUtil.dp2px(context, 24f + 48f + 16f + 96f + 4f)        logger.d(TAG, "onResume height: $rowHeight padding $scrollDistance")        if (rowHeight != null) {            binding.recyclerView.smoothScrollBy(0, rowHeight - scrollDistance)        }    }}





