package com.danale.edge.ui.userfaceimport android.annotation.SuppressLintimport android.app.Activityimport android.content.Intentimport android.os.Bundleimport androidx.activity.viewModelsimport com.danale.edge.Rimport com.danale.edge.base.BaseActivityimport com.danale.edge.base.BaseNavigation.Constantsimport com.danale.edge.ui.userface.UserFaceViewModel.Companion.REQUEST_CODEimport com.danale.edge.usersdk.usecase.UserSdkUseCaseimport com.google.gson.Gsonimport dagger.hilt.android.AndroidEntryPointimport io.reactivex.rxjava3.kotlin.subscribeByimport io.reactivex.rxjava3.schedulers.Schedulersimport java.nio.charset.StandardCharsetsimport javax.inject.Inject@AndroidEntryPointclass UserFaceActivity : BaseActivity() {    private val viewModel: UserFaceViewModel by viewModels()    @Inject    lateinit var userSdk: UserSdkUseCase    @Inject    lateinit var gson: Gson    // 当前点击的人脸下标     private var mainPosition: Int? = 0    companion object {        const val CURRENT_USER_FACE = "CURRENT_USER_FACE"    }    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        setContentView(R.layout.activity_user_face)    }    @SuppressLint("CheckResult")    override fun onResume() {        super.onResume()        // 拿到当前用户下标        mainPosition = intent?.getIntExtra(Constants.EXTRA_SEARCH_MAIN_POSITION, 0)        viewModel.loadSearchHistoryItems(mainPosition)        /**         * 加载人脸的好友数据         * */        userSdk.loadAssistData(CURRENT_USER_FACE)            .subscribeOn(Schedulers.io())            .subscribeBy(onSuccess = {                val cb = StandardCharsets.UTF_8.decode(it)                val json = cb.toString()                logger.d(                    TAG,                    "decode, buffer=${it?.remaining()}, json=${json}"                )                val mapData = gson.fromJson(json, MutableMap::class.java)                val name = mapData[mainPosition.toString()]                viewModel.setName(name as String?)            }, onError = {                logger.w(TAG, "load assist, buffer, error", it)            })    }  	/**  	* 这里用到了startActivityForResult，用于页面带参数返回，参考  	* https://blog.csdn.net/weixin_41008021/article/details/90346700  	*/    @Deprecated("Deprecated in Java")    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {        super.onActivityResult(requestCode, resultCode, data)        when (requestCode) {            REQUEST_CODE -&gt; {                if (resultCode == Activity.RESULT_OK) {                    if (data != null) {                        viewModel.setName(data.getStringExtra(Constants.EXTRA_SEARCH_MAIN_POSITION))                    }                }            }        }    }}



