ViewModelpackage com.danale.edge.ui.userfaceimport android.annotation.SuppressLintimport android.app.Applicationimport android.content.Intentimport android.view.Viewimport androidx.databinding.ObservableFieldimport androidx.lifecycle.viewModelScopeimport com.danale.edge.base.BaseNavigationimport com.danale.edge.base.BaseViewModelimport com.danale.edge.intelligence.IntelligenceRepositoryimport com.danale.edge.ui.common.adapter.PersonAdapterimport com.danale.edge.ui.common.adapter.ThumbnailAdapterimport com.danale.edge.ui.common.callback.RecyclerItemOnClickimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.launchimport kotlinx.coroutines.withContextimport javax.inject.Inject@HiltViewModelclass UserFaceViewModel @Inject constructor(application: Application) : BaseViewModel(application),    RecyclerItemOnClick&lt;ThumbnailAdapter.ThumbnailViewHolder&gt; {    @Inject    lateinit var ai: IntelligenceRepository    // 当前用户名称    var currentUserName = ObservableField("")    private var mainPosition = 0    // 用于给activity传参的标志    companion object {        const val REQUEST_CODE = 1    }    /**     * 当前页面的头像     * */    val searchPersonAdapter =        PersonAdapter(itemOnClick = object : RecyclerItemOnClick&lt;PersonAdapter.PersonViewHolder&gt; {            override fun onClickItem(viewHolder: PersonAdapter.PersonViewHolder) {                logger.d(TAG, "onClickPerson=$viewHolder")            }        })    /**     * 加载当前点击的人脸图片     * */    @SuppressLint("NotifyDataSetChanged")    fun loadSearchHistoryItems(position: Int?) {        if (position != null) {            mainPosition = position        }        viewModelScope.launch {            val faceUsers = withContext(Dispatchers.IO) {                ai.getFaceUserList()            }            searchPersonAdapter.list.clear()            searchPersonAdapter.list.add(faceUsers[position!!])            // fixme: SuppressLint 后续换SortedList            searchPersonAdapter.notifyDataSetChanged()        }    }    /**     * 设置名称     * */    @SuppressLint("NotifyDataSetChanged")    fun setName(name: String?) {        logger.d(TAG, "setName, name = $name")        currentUserName.set(name)    }    /**     * 点击设置名称     * */    @Suppress("UNUSED_PARAMETER") // View.OnClickListener    fun onClickSetFriend(view: View) {        val intent = Intent().apply {            putExtra(                BaseNavigation.Constants.EXTRA_SEARCH_MAIN_POSITION,                mainPosition,            )        }      	// BaseNavigation封装的方法        navigationRequiredEvent.postValue(            BaseNavigation(                BaseNavigation.Route.USER_FACE_FRIEND_LIST,                intent,                true,                REQUEST_CODE            )        )    }    override fun onClickItem(viewHolder: ThumbnailAdapter.ThumbnailViewHolder) {        logger.d(TAG, "viewHolder=$viewHolder")    }}

这里的跳转用到了onActivityResult， 使用的是BaseNavigation封装后的方法，第三个参数为是否开启startForResult，第四个参数是标志
封装的方法如下：
fun launch(fromActivity: Activity, intent: Intent? = null) {  val finalIntent = Intent(fromActivity, route.activityClass)  paramIntent?.let { finalIntent.putExtras(it) }  intent?.let { finalIntent.putExtras(it) }  if (startForResult) {      fromActivity.startActivityForResult(finalIntent, requestCode, requestBundle)  } else {      fromActivity.startActivity(finalIntent)  }}

每次跳转都会走到launch函数中
