ViewModelcom/danale/edge/ui/userface/UserFaceFriendListViewModel.kt
package com.danale.edge.ui.userfaceimport android.annotation.SuppressLintimport android.app.Applicationimport androidx.lifecycle.MutableLiveDataimport com.danale.edge.base.BaseViewModelimport com.danale.edge.ui.common.adapter.ThumbnailAdapterimport com.danale.edge.ui.common.callback.RecyclerItemOnClickimport com.danale.edge.ui.common.groupie.UserFaceFriendItemimport com.danale.edge.usersdk.usecase.UserSdkUseCaseimport com.google.gson.Gsonimport com.xwray.groupie.GroupieAdapterimport com.xwray.groupie.Sectionimport dagger.hilt.android.lifecycle.HiltViewModelimport io.reactivex.rxjava3.kotlin.subscribeByimport io.reactivex.rxjava3.schedulers.Schedulersimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.rx3.awaitLastimport kotlinx.coroutines.rx3.awaitSingleOrNullimport kotlinx.coroutines.withContextimport org.json.JSONExceptionimport org.json.JSONObjectimport java.nio.charset.StandardCharsetsimport javax.inject.Inject@HiltViewModelclass UserFaceFriendListViewModel @Inject constructor(application: Application) :    BaseViewModel(application),    RecyclerItemOnClick&lt;ThumbnailAdapter.ThumbnailViewHolder&gt; {    // 用于加载页面的Adapter    val starUserAdapter = GroupieAdapter()    // 最终列表中的数据格式    data class UserFaceFriend(        var name: String?,        var url: String?,        var nameId: String?    )    // 最终求交集的星标列表    private var userFaceFriendList = ArrayList&lt;UserFaceFriend&gt;()    private var mainPosition = 0    @Inject    lateinit var userSdk: UserSdkUseCase    @Inject    lateinit var gson: Gson    val liveData = MutableLiveData&lt;String&gt;()    companion object {        const val CURRENT_USER_FACE = "CURRENT_USER_FACE"    }    /**     * 拿到对应position     * */    fun setPosition(position: Int) {        mainPosition = position    }    /**     * 加载好友列表     */    suspend fun loadPlatformContactList(refresh: Boolean = false) {        try {            // 获取的好友列表            withContext(Dispatchers.IO) {                sdk.getFriendsList(forceReFetch = refresh).awaitLast().map {                    // 用户名                    val displayName = if (it.remarkName?.isNotEmpty() == true) {                        it.remarkName                    } else {                        it.likeName                    }                    // 用户头像                    val url = withContext(Dispatchers.IO) {                        it.userName?.let { it1 -&gt;                            sdk.getPhotoUrlByPlatformUserName(it1).awaitSingleOrNull()                        }                    }                    // 添加数据                    userFaceFriendList.add(                        UserFaceFriend(                            displayName,                            url,                            it.userName                        )                    )                }            }            // 构建列表            buildSettingItems()        } catch (e: Exception) {            toastError(e)        }    }    /**     * 构建好友列表     * */    @SuppressLint("CheckResult")    private fun buildSettingItems() {        logger.d(TAG, "buildSettingItems starFriendList=${userFaceFriendList}")        starUserAdapter.apply {            add(Section().apply {                for ((i, item) in userFaceFriendList.withIndex()) {                    item.url?.let { url -&gt;                        item.name?.let { name -&gt;                            UserFaceFriendItem(                                avatar = url,  // 头像链接                                name = name,  // 用户名                                clickListener = {                                    // 加载数据                                    userSdk.loadAssistData(CURRENT_USER_FACE)                                        .subscribeOn(Schedulers.io())                                        .subscribeBy(onSuccess = {                                            val cb = StandardCharsets.UTF_8.decode(it)                                            val json = cb.toString()                                            val mapJson = if (json == "null") {                                                val data = mapOf("$mainPosition" to name)                                                gson.toJson(data)                                            } else {                                                val mapData = getMap(json)                                                // 添加数据                                                mapData?.set(mainPosition.toString(), name)                                                gson.toJson(mapData)                                            }                                            //更新数据                                            userSdk.storeAssistData(                                                CURRENT_USER_FACE, mapJson.toByteArray(StandardCharsets.UTF_8)                                            )                                                .subscribeOn(Schedulers.io())                                                .subscribeBy(onSuccess = {                                                    logger.d(TAG, "updateFaceUserList, buffer, success")                                                }, onError = { e -&gt;                                                    logger.e(TAG, "updateFaceUserList, buffer, error",e)                                                })                                            // 传递给liveData通知activity跳转                                            liveData.postValue(mainPosition.toString())                                        }, onError = {                                            logger.w(TAG, "load assist, buffer, error", it)                                        })                                }                            )                        }                    }?.let { add(it) }                }            })        }    }    private fun getMap(jsonString: String?): HashMap&lt;String, Any&gt;? {        val jsonObject: JSONObject        try {            jsonObject = jsonString?.let { JSONObject(it) }!!            val keyIter: Iterator&lt;String&gt; = jsonObject.keys()            var key: String            var value: Any            val valueMap = HashMap&lt;String, Any&gt;()            while (keyIter.hasNext()) {                key = keyIter.next()                value = jsonObject[key] as Any                valueMap[key] = value            }            return valueMap        } catch (e: JSONException) {            e.printStackTrace()        }        return null    }    override fun onClickItem(viewHolder: ThumbnailAdapter.ThumbnailViewHolder) {        logger.d(TAG, "viewHolder=$viewHolder")    }}


