open class LabelPipeline&lt;T : Any&gt;(    private val extractors: List&lt;LabelExtractor&lt;T&gt;&gt;,    private val logger: Logger,    private val providedSink: EventSink?) : Closeable {    companion object {        const val TAG = "LabelPipeline"    }    init {        extractors.forEach {            if (providedSink != null) {                logger.i(TAG, "init, sink ${it.hashCode()} to ${providedSink.hashCode()}")                it.bindEventSink(providedSink)            }        }    }    fun process(item: T, metaData: LabeledObject.MetaData): Single&lt;LabeledObject&lt;T&gt;&gt; {        var single = Single.just(LabeledObject(ConcurrentHashMap(), item, metaData = metaData))        for (op in extractors) {            single = single.flatMap { op.extractLabel(it).toSingleDefault(it) }        }        return single    }    class Builder&lt;T : Any&gt;(val logger: Logger) {        private val list = LinkedList&lt;LabelExtractor&lt;T&gt;&gt;()        private var sink: EventSink? = null        fun sinkTo(sink: EventSink): Builder&lt;T&gt; {            this.sink = sink            return this        }        fun addOp(extractor: LabelExtractor&lt;T&gt;): Builder&lt;T&gt; {            list.addLast(extractor)            return this        }        fun build(): LabelPipeline&lt;T&gt; {            return LabelPipeline(list, logger, sink)        }    }    override fun close() {        for (op in extractors) {            op.flushSession(providedSink)            op.close()        }    }}



interface LabelExtractor&lt;T : Any&gt; : Closeable, EventSource {    /**     * Extractor执行计算     */    fun extractLabel(item: LabeledObject&lt;T&gt;): Completable    /**     * 告知计算已结束，Extractor应将尚未上报的事件进行上报     */    fun flushSession(sink: EventSink?) {}    fun labelKey(sourceType: String, category: String, vendor: String, vendorKey: String): String {        return "$sourceType:$category:$vendor:$vendorKey"    }}



