com/danale/edge/ui/flow/VideoFlowViewModel.kt
fun attachPlayer(        surface: Surface,        clipDri: String,        clipDataSource: ByteBufferVideoSource? = null,        positionResponder: ClipPositionResponder? = null    ) {        logger.d(            TAG,            "attachPlayer, clipDri=${Fuzzy.interval(clipDri)}, data=${clipDataSource?.hashCode()}"        )        positionResponder?.let {            // 弱引用保存播放进度的响应体            weakPositionResponder = WeakReference(it)        }        loadPlayerExecutor.submit {            detachPlayerSync()            if (player == null) {                logger.i(TAG, "attachPlayer, instantiate")                player = IjkPlayerProvider.provideIjkPlayerDefaultConfig()            }            player?.apply {                try {                    setSurface(surface)                    setOnPreparedListener {                      // 开始播放视频                    }                    setOnErrorListener { mediaPlayer, errArg1, errArg2 -&gt;                        // 错误被处理                    }                    setOnCompletionListener {                        // 视频播放完毕                    }                } catch (e: Exception) {                    logger.e(TAG, "attachPlayer, null mp", e)                }            }            if (clipDataSource != null) {                logger.i(TAG, "attachPlayer, use exist data")                try {                    // 播放已有视频                } catch (e: Exception) {}            } else {                logger.i(TAG, "attachPlayer, load clip ${Fuzzy.interval(clipDri)}")                val latch = CountDownLatch(1)                dataSubscription = sdk.getBlobWithDri(clipDri)                    .subscribeOn(Schedulers.io())                    .subscribeBy(                        onSuccess = {                            logger.i(TAG, "attachPlayer, blob ok")                            try {                                val data = ByteBufferVideoSource()                                data.load(it)                                preparePlayer(data)                                /***保存bytebuffer****/                               saveBytebuffer(it, clipDri.split("clip_")[1])                            } catch (e: Exception) {}                            latch.countDown()                        },                        onError = {}                    )                latch.await()            }        }    }

其中data.load(it)是获取视频来源，it是ByteBuffer格式，通过保it为MP4格式可以实现视频的导出，不同的视频通过clipDri加以区分
// 获取存储路径private fun getPath(): String {    val result = (Environment.getExternalStorageDirectory().toString()            + File.separator + Environment.DIRECTORY_DCIM            + File.separator + "Camera" + File.separator)    val file = File(result)    if (!file.exists()) {        file.mkdir()    }    return result + File.separator}// 保存ByteBufferprivate fun saveBytebuffer(byteBuffer: ByteBuffer, fileName: String){    logger.d(TAG, "attachPlayer, save bytebuffer")    val file = File(getPath()+ fileName + ".mp4")    logger.d(TAG, "attachPlayer, file=$file")    if(!file.exists()){        file.createNewFile();    }    val os: OutputStream = FileOutputStream(file,true)    os.write(byteBuffer.array())    os.flush()    os.close()}

