视频导入图片导入通过ffmpeg将mp4视频文件分割成jpg图片文件
ffmpeg -i  test.mp4 -r 10 -f image2 %05d.jpg


-i : 指定输入文件
-r : 帧数 10
-f : 指定格式化的格式为image2
image2后面跟着的是文件名
%5d：以为5位数按正序编号

将图片放入到app的文件夹中，由于手机的安全性，放入其他文件夹会读不到文件/sdcard/Android/data/com.alcidae.edgeapp/files
通过context.getExternalFilesDir(null)获取到文件夹路径，存入每个图片的名称
private fun getPics(): MutableList&lt;String&gt; {    logger.d(TAG, "start getPics, ${context.getExternalFilesDir(null)}")    val fileNames: MutableList&lt;String&gt; = mutableListOf()    val fileTree = File("${context.getExternalFilesDir(null)}/test").walk()    fileTree.maxDepth(1) //需遍历的目录层次为1，即无须检查子目录        .filter {            it.isFile        } //只挑选文件，不处理文件夹        .filter {            it.extension in listOf("jpg")        }//选择扩展名为jpg的文件        .forEach {            fileNames.add(it.absolutePath)        }//循环 处理符合条件的文件    return fileNames}

通过循环读取图片，并将图片转成bitmap输入到pipeline
@SuppressLint("CheckResult")private fun pipelineFromPic(files: MutableList&lt;String&gt;) {    for (i in  0 until files.size){        val file = File(files[i])        //readBytes读取字节数组形式的文件内容        val bytes = file.readBytes()        //decodeByteArray从字节数组解析图片        val currBitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)        val metaData =            LabeledObject.MetaData(dataTimestamp = i.toLong())  // 新建data 承载源数据        videoPipeline.process(currBitmap, metaData)            // 扁平化            .flatMap {                val elapsedNano = it.getElapsedMillis()                logger.d(TAG, "for, inferenceTime = $elapsedNano")                it.obj.recycle()  // 释放与此位图关联的本机对象，并清除对像素数据的引用                return@flatMap Single.just(it)  // 转换为发出该对象的Single            }            .subscribeBy(                onSuccess = {                    logger.d(TAG, "for, onSuccess, i=$i, labeledObject = $it")                },                onError = {                    logger.d(TAG, "for, onError, i=$i, throwable = $it")                    close()                },            )    }    videoPipeline.close()}

