音频导入通过ffmpeg工具将mp4文件转成pcm文件
ffmpeg -i test.mp4 test.mp3ffmpeg -i test.mp3 -ar 48000 -ac 2 -f s16le test.pcm

@SuppressLint("CheckResult")fun videoPipeline() {    val file = File("${context.getExternalFilesDir(null)}/test/test.pcm")    val bytes = file.readBytes()    val metaData = LabeledObject.MetaData(dataTimestamp = 1.toLong())    logger.d(TAG, "bytes.size= ${bytes.size}")    val step = 640  // 每次读取的大小    val num = floor((bytes.size / step).toDouble())  // 循环次数    for (i in 0 until num.toInt()) {        val byte = bytes.slice(i..i + step)  // 截取pcm        val shorts = ShortArray(byte.size / 2) {            (byte[it * 2].toUByte().toInt() + (byte[(it * 2) + 1].toInt() shl 8)).toShort()        }  // 转换成shortArray        Maybe.fromSingle(audioPipeline.process(shorts, metaData)            .flatMap {                val elapsedNano = it.getElapsedMillis()                logger.d(TAG, "audioPipe, inferenceTime = $elapsedNano")                return@flatMap Single.just(it)            }).subscribeBy(            onSuccess = {                logger.d(TAG, "for, onSuccess, labeledObject = $it")            },            onError = {                logger.d(TAG, "for, onError, throwable = $it")                close()            },        )    }    audioPipeline.close()}

