package com.danale.edge.usersdk.operationimport com.danale.edge.foundation.log.Loggerimport com.danale.edge.usersdk.jni.BaseJsonOperationimport com.danale.edge.usersdk.jni.BaseResponseimport com.google.gson.Gsonimport com.google.gson.annotations.SerializedNameclass GetDeviceSettingListOp (val param: Param, logger: Logger, gson: Gson) :    BaseJsonOperation&lt;GetDeviceSettingListOp.Response&gt;(logger, gson) {    // 这里是回调    override fun unmarshallSerializedResponse(jsonOutput: String?): Response {        val response = Response()        val array = gson.fromJson(jsonOutput, Array&lt;ResultBean&gt;::class.java)        response.list = array        return response    }    // 传入数据    override fun performOperation(context: CallbackContext) {        context.nativeResponseCallback(0, 0, "", mockList)  // 在这里使用mock数据    }    // 入参    class Param(        @SerializedName("device_id") val deviceId: String,        @SerializedName("device_type") val deviceType: Int,    )      // 出参    class Response : BaseResponse() {      // 返回一个Array        var list: Array&lt;ResultBean&gt;? = null        override fun toString(): String {            return "Response(list=${list?.contentToString()})"        }    }    class ResultBean {        @SerializedName("name")        val name: String? = null        @SerializedName("items")        val items: Array&lt;Item&gt;? = null        override fun toString(): String {            return "ResultBean(name=$name, items=$items)"        }    }    class Item {        @SerializedName("id")        val id: String? = null        @SerializedName("type")        val type: String? = null        @SerializedName("subId")        val subId: String? = null        override fun toString(): String {            return "Item(id=$id, type=$type, subId=$subId)"        }    }}

